snippets.react:
import { DataGrid, type DataGridColumn, type DataGridRow } from '@design-schema/react';

const columns: DataGridColumn[] = [
  { key: 'sku', header: 'SKU', isRowHeader: true, width: 160, pinned: 'start' },
  { key: 'name', header: 'Name', sortable: true, resizable: true },
  { key: 'category', header: 'Category', sortable: true },
  { key: 'price', header: 'Price (USD)', abbr: 'Price in US dollars', align: 'end' },
  { key: 'stock', header: 'Qty', abbr: 'Quantity in stock', align: 'end' },
];

const names = ['Widget', 'Sprocket', 'Gear', 'Flange', 'Bracket', 'Hinge', 'Spring', 'Valve'];

const categories = ['Hardware', 'Fittings', 'Motion'];

const data: DataGridRow[] = Array.from({ length: 200 }, (_, index) => ({
  id: `row-${index}`,
  sku: `A-${1000 + index}`,
  name: `${names[index % names.length]} ${Math.floor(index / names.length) + 1}`,
  category: categories[index % categories.length],
  price: ((index * 37) % 500) + 10,
  stock: (index * 13) % 90,
}));

<DataGrid caption="Price list" columns={columns} data={data} />

snippets.lit:
import '@design-schema/lit';
import { html } from 'lit';
import type { DataGridColumn, DataGridRow } from '@design-schema/lit';

const columns: DataGridColumn[] = [
  { key: 'sku', header: 'SKU', isRowHeader: true, width: 120, pinned: 'start' },
  { key: 'name', header: 'Name', width: 200, resizable: true, editable: true, editor: 'text' },
  {
    key: 'price',
    header: 'Price (USD)',
    align: 'end',
    sortable: true,
    editable: true,
    editor: 'number',
    width: 120,
    validate: (value) => (typeof value === 'number' && value >= 0 ? undefined : 'Enter a price of 0 or more.'),
  },
  { key: 'qty', header: 'Qty', abbr: 'Quantity', align: 'end', sortable: true, width: 80 },
  {
    key: 'category',
    header: 'Category',
    width: 160,
    editable: true,
    editor: 'select',
    options: [
      { value: 'hardware', label: 'Hardware' },
      { value: 'software', label: 'Software' },
    ],
  },
  { key: 'inStock', header: 'In stock', width: 96, editable: true, editor: 'checkbox' },
];

const data: DataGridRow[] = [
  { id: 'a', sku: 'A-1', name: 'Widget', price: 10, qty: 240, category: 'hardware', inStock: true },
  { id: 'b', sku: 'B-2', name: 'Sprocket', price: 20, qty: 85, category: 'hardware', inStock: true },
  { id: 'c', sku: 'C-3', name: 'License', price: 199, qty: 12, category: 'software', inStock: false },
  { id: 'd', sku: 'D-4', name: 'Gear', price: 45, qty: 4, category: 'hardware', inStock: true },
  { id: 'e', sku: 'E-5', name: 'Plan', price: 15, qty: 500, category: 'software', inStock: true },
];

html`
  <ds-data-grid
    caption="Price list"
    caption-level="2"
    .columns=${columns}
    .data=${data}
    selectable="none"
    density="compact"
    height="viewport"
  ></ds-data-grid>
`;

